tool.command:

  ln -f -s ${input_insert_gro_path} ${input_insert_gro_path}_`echo $$`.${input_insert_gro_path.ext};

  ln -f -s ${input_gro_path} ${input_gro_path}_`echo $$`.${input_gro_path.ext};

  ln -f -s ${input_positions_dat_path} ${input_positions_dat_path}_`echo $$`.${input_positions_dat_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

insert_molecules

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__nmol__dq__:${properties.nmol},__dq__box__dq__:__dq__${properties.box}__dq__,__dq__tries__dq__:${properties.tries},__dq__seed__dq__:${properties.seed},__dq__radius__dq__:${properties.radius},__dq__scale__dq__:${properties.scale},__dq__dr__dq__:__dq__${properties.dr}__dq__,__dq__rot__dq__:__dq__${properties.rot}__dq__,__dq__gmx_lib__dq__:__dq__${properties.gmx_lib}__dq__,__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_insert_gro_path) != 'None':
    --input_insert_gro_path ${input_insert_gro_path}_`echo $$`.${input_insert_gro_path.ext}
  #end if

  #if str($input_gro_path) != 'None':
    --input_gro_path ${input_gro_path}_`echo $$`.${input_gro_path.ext}
  #end if

  #if str($input_positions_dat_path) != 'None':
    --input_positions_dat_path ${input_positions_dat_path}_`echo $$`.${input_positions_dat_path.ext}
  #end if


  --output_gro_path $outname_output_gro_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_insert_gro_path}_`echo $$`.${input_insert_gro_path.ext};

  rm -f ${input_gro_path}_`echo $$`.${input_gro_path.ext};

  rm -f ${input_positions_dat_path}_`echo $$`.${input_positions_dat_path.ext};


  if test -f $outname_output_gro_path; then mv $outname_output_gro_path $output_gro_path; fi;
